/**
 * @fileoverview The context the owner package hands a module (#714): closures that reach the instance through the
 * host's own `api` handle, as rummage's `ctx.commands.register` (a `lockCaller` pin), its `slothlet.metadata` and
 * `slothlet.event` calls and its `host.*` leaves do. It is a file of the package that created the instance, but not
 * the file that called `slothlet()`.
 * @module owner-host/context
 */

/**
 * Build the context.
 * @param {object} api - The bound api the host's `slothlet()` call returned.
 * @returns {Record<string, Function>} The context.
 */
export function makeContext(api) {
	return {
		pin: (fn) => typeof api.slothlet.lockCaller(fn),
		meta: () => api.slothlet.metadata.caller()?.apiPath ?? null,
		emit: () => {
			api.slothlet.event.emit("host:ping", { n: 1 });
			return "emitted";
		},
		hostLeaf: () => api.host.echo("x")
	};
}
